n, m = map(int, input().split())
graph = [[] for _ in range(n)]
for _ in range(m):
    a, b = map(int, input().split())
    graph[a - 1].append(b - 1)
    graph[b - 1].append(a - 1)
seen, answer = set(), 0
for start in range(n):
    if start in seen:
        continue
    answer += 1
    seen.add(start)
    stack = [start]
    while stack:
        v = stack.pop()
        for u in graph[v]:
            if u not in seen:
                seen.add(u)
                stack.append(u)
print(answer)
